#!/usr/bin/env node
// Checks the protocol definition and everything generated from it:
//
//   1. regenerates into a temp dir and fails if a committed generated file differs (or a stale
//      file lies in packages/protocol/src/generated);
//   2. validates constants.json and every fixture against its schema (ajv, strict mode),
//      including JSON carried in strings (contentMediaType + contentSchema) — see validate.mjs;
//   3. requires at least one fixture per message schema;
//   4. compiles the C++ header on the host (C++11 and C++17), when a compiler is available.
//
//   npm run protocol:check
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { generate, outputs, writeOutputs } from './gen.mjs';
import { fixturesDir, isMessageSchema, listFiles, protocolDir, readJson, repoRoot } from './schemas.mjs';
import { createValidator } from './validate.mjs';

const problems = [];
const fail = (msg) => problems.push(msg);

// ------------------------------------------------------------------ 1. generated files

const tmp = mkdtempSync(join(tmpdir(), 'protocol-check-'));
try {
  const files = generate();
  writeOutputs(files, tmp);
  for (const rel of files.keys()) {
    const committed = join(repoRoot, rel);
    if (!existsSync(committed)) {
      fail(`${rel} is missing — run: npm run protocol:gen`);
    } else if (readFileSync(committed, 'utf8') !== readFileSync(join(tmp, rel), 'utf8')) {
      fail(`${rel} is out of date — run: npm run protocol:gen`);
    }
  }
  const tsDir = 'packages/protocol/src/generated';
  const expected = new Set([...files.keys()].filter((p) => p.startsWith(`${tsDir}/`)));
  for (const name of readdirSync(join(repoRoot, tsDir))) {
    if (!expected.has(`${tsDir}/${name}`)) fail(`${tsDir}/${name} is not generated by protocol/scripts/gen.mjs — delete it`);
  }

  // ---------------------------------------------------------------- 4. C++ header compiles
  const cxx = process.env.CXX || 'c++';
  if (spawnSync(cxx, ['--version'], { stdio: 'ignore' }).status === 0) {
    // Included twice (include guard) next to a few uses, as firmware code would.
    const unit = [
      `#include "${join(tmp, outputs.header)}"`,
      `#include "${join(tmp, outputs.header)}"`,
      'static_assert(protocol::NUM_LEDS_MAX == protocol::ESP32_MAX_LEDS, "");',
      'static_assert(protocol::GAMMA_MIN < protocol::GAMMA_DEFAULT, "");',
      'int main() { return protocol::DISCOVERY_MAGIC[0] == \'A\' ? 0 : 1; }',
      '',
    ].join('\n');
    for (const std of ['c++11', 'c++17']) {
      try {
        execFileSync(cxx, [`-std=${std}`, '-Wall', '-Wextra', '-Werror', '-fsyntax-only', '-x', 'c++', '-'], { input: unit, stdio: 'pipe' });
      } catch (e) {
        fail(`${outputs.header} does not compile with ${cxx} -std=${std}:\n${e.stderr}`);
      }
    }
  } else {
    console.warn(`warning: no C++ compiler (${cxx}); the header compile check was skipped`);
  }
} finally {
  rmSync(tmp, { recursive: true, force: true });
}

// --------------------------------------------------------------------- 2./3. validation

const { ajv, schemas, check } = createValidator();

const constantsSchema = readJson(join(protocolDir, 'constants.schema.json'));
const validateConstants = ajv.compile(constantsSchema);
if (!validateConstants(readJson(join(protocolDir, 'constants.json')))) {
  fail(`constants.json: ${ajv.errorsText(validateConstants.errors)}`);
}

// fixtures/<dir>/<name>[.<variant>].json → schemas/<dir>/<name>.schema.json
const fixturesBySchema = new Map();
for (const fixture of listFiles(fixturesDir, '.json')) {
  const [, dir, name] = /^(.*\/)?([^./]+)(?:\.[^/]+)?\.json$/.exec(fixture) ?? [];
  const schemaFile = `${dir ?? ''}${name}.schema.json`;
  if (!schemas.has(schemaFile)) {
    fail(`fixtures/${fixture}: no schema ${schemaFile}`);
    continue;
  }
  if (!fixturesBySchema.has(schemaFile)) fixturesBySchema.set(schemaFile, []);
  fixturesBySchema.get(schemaFile).push(fixture);
}

let validated = 0;
for (const [file, schema] of schemas) {
  if (!isMessageSchema(schema)) continue;
  const fixtures = fixturesBySchema.get(file) ?? [];
  if (!fixtures.length) fail(`schemas/${file}: no fixture in fixtures/${file.replace('.schema.json', '.json')}`);
  for (const fixture of fixtures) {
    const found = check(schema.$id, readJson(join(fixturesDir, fixture)), `fixtures/${fixture}`);
    for (const p of found) fail(p);
    if (!found.length) validated++;
  }
}

if (problems.length) {
  for (const p of problems) console.error(`✗ ${p}`);
  process.exit(1);
}
console.log(`✓ generated files are up to date; constants.json and ${validated} fixtures are valid`);
